// --- Carried corner residual ----------------------------------------------------------
//
// ONE defect, one correction: a body that ACTUALLY reached a vertex and ACTUALLY
// crossed its incoming plane must not be frozen for the rest of the route by the
// small arc residual its own overshoot created. Everything else the frontier
// rule refuses, it still refuses, because every condition below has to hold at
// once and each one is a physical fact:
//
//   1. The credit is PINNED — a positive displacement bought no progress at all.
//   2. It is pinned at EXACTLY a vertex's arc, so the whole incoming leg was
//      credited. A cut corner pins BELOW the vertex arc (0.18 early pins at
//      3.82, never at 4) and therefore never qualifies, which is what keeps the
//      z 15.82 refusal and its return-and-re-traverse repair intact.
//   3. The body is PAST that vertex's incoming plane, not short of it.
//   4. Payment comes from displacement the body actually walked WHILE pinned at
//      this very vertex, banked from nowhere else and reset the moment credit
//      moves or the pin changes. A far-end wiggle banks against the vertex it is
//      standing at, never against an unfinished corner behind it.
//   5. Payment may not cross the NEXT vertex, so the bank can only ever settle
//      the leg the body is demonstrably on; it can never buy a leg ahead.
//   6. Payment may not exceed the body's own straight-line distance from the
//      vertex: it cannot have travelled further from the corner than it is.
//
// The bank is a grant of nothing. It is displacement the body really spent, held
// against the one corner it really rounded, and it is destroyed unspent whenever
// the pin moves. Stationary bodies bank nothing (1), and no timer, tolerance,
// corridor, vertex, arrival or reference rule changes here.

/** Live, non-persisted accounting state for the corner the credit is pinned at. */
export interface RouteCreditCorner {
  /** Route index the credit is pinned at, or -1 when it is not pinned. */
  readonly vertexIndex: number;
  /** Displacement actually walked while pinned at that vertex. */
  readonly bankedUnits: number;
}

export interface RouteCreditStep {
  readonly units: number;
  readonly corner: RouteCreditCorner;
}

export const NO_ROUTE_CREDIT_CORNER: RouteCreditCorner = Object.freeze({
  vertexIndex: -1,
  bankedUnits: 0
});

/** Arc length from the head of the route to `index`. */
function arcAtVertex(route: readonly CommonGroundPoint[], index: number): number {
  let arc = 0;
  for (let i = 1; i <= index && i < route.length; i += 1) {
    arc += distanceBetween(route[i - 1], route[i]);
  }
  return arc;
}

/**
 * The vertex whose arc the credit is pinned at EXACTLY, or -1.
 *
 * The comparison is a floating-point identity check, not a tolerance: the pin
 * lands on the vertex arc because the incoming leg's projection clamps there, so
 * anything further away than accumulated rounding is a body that stopped short.
 */
function pinnedVertexIndex(route: readonly CommonGroundPoint[], units: number): number {
  let arc = 0;
  for (let index = 1; index < route.length; index += 1) {
    arc += distanceBetween(route[index - 1], route[index]);
    if (Math.abs(arc - units) <= 1e-9 * Math.max(1, arc)) return index;
  }
  return -1;
}

/** True when the body is on the far side of the plane through `route[index]`. */
function pastIncomingPlane(
  route: readonly CommonGroundPoint[],
  index: number,
  body: CommonGroundPoint
): boolean {
  if (index <= 0 || index >= route.length) return false;
  const from = route[index - 1];
  const at = route[index];
  const length = distanceBetween(from, at);
  if (!(length > 0)) return false;
  const along = ((body.x - at.x) * (at.x - from.x)
    + (body.y - at.y) * (at.y - from.y)
    + (body.z - at.z) * (at.z - from.z)) / length;
  return along >= 0;
}

/**
 * `routeProgressUnits`, plus the carried-residual correction and its state.
 *
 * The frontier rule runs FIRST and unchanged. Only when it credits nothing at
 * all for real movement does the corner accounting get a say, and only under the
 * six conditions above.
 */
export function nextRouteCredit(
  route: readonly CommonGroundPoint[],
  body: CommonGroundPoint,
  previousUnits: number,
  displacementUnits: number,
  corner: RouteCreditCorner = NO_ROUTE_CREDIT_CORNER,
  corridorRadius = 2.5
): RouteCreditStep {
  const plain = routeProgressUnits(route, body, previousUnits, displacementUnits, corridorRadius);
  // Credit moved, or the body did not: either way there is no pinned corner to
  // settle and nothing to bank. A stationary body banks NOTHING.
  if (plain > previousUnits) return { units: plain, corner: NO_ROUTE_CREDIT_CORNER };
  if (!(displacementUnits > 0)) return { units: plain, corner };

  const index = pinnedVertexIndex(route, previousUnits);
  if (index < 0 || !pastIncomingPlane(route, index, body)) {
    // A cut corner pins short of the vertex arc and stays refused here.
    return { units: plain, corner: NO_ROUTE_CREDIT_CORNER };
  }

  const banked = (corner.vertexIndex === index ? corner.bankedUnits : 0) + displacementUnits;
  const vertexArc = arcAtVertex(route, index);
  const nextArc = index + 1 < route.length
    ? vertexArc + distanceBetween(route[index], route[index + 1])
    : vertexArc;
  const reach = Math.min(
    previousUnits + banked,
    nextArc,
    vertexArc + distanceBetween(body, route[index])
  );
  // The same scan, the same corridor, the same monotonic frontier — only the
  // allowance for THIS corner differs, and it is spent displacement.
  const settled = routeProgressUnits(
    route, body, previousUnits, Math.max(0, reach - previousUnits), corridorRadius
  );
  if (settled > previousUnits) return { units: settled, corner: NO_ROUTE_CREDIT_CORNER };
  return { units: previousUnits, corner: { vertexIndex: index, bankedUnits: banked } };
}

