    );
    expect(cut.units).toBe(4);
    expect(cut.corner.vertexIndex).toBe(-1);

    // Nor does standing short of the plane on the cut line qualify.
    const short = nextRouteCredit(
      CG_ROUTE_COMMON, { x: -43, y: CG_POSES.E.y, z: 15.82 }, 4, 0.15
    );
    expect(short.units).toBe(4);
    expect(short.corner.vertexIndex).toBe(-1);
  });

  it('refuses a far-end wiggle and a distant loop against an unfinished corner', () => {
    let units = 4;
    let corner = NO_ROUTE_CREDIT_CORNER;
    for (let frame = 0; frame < 400; frame += 1) {
      const at = { x: -48, y: CG_POSES.E.y, z: 12 + (frame % 2) * 0.4 };
      const step = nextRouteCredit(CG_ROUTE_COMMON, at, units, 0.4, corner);
      units = step.units;
      corner = step.corner;
    }
    expect(units).toBe(4);
  });

  it('cannot buy the leg ahead: payment stops at the next vertex', () => {
    // Pinned at (-44, 16) with a huge bank and a body improbably far along the
    // next leg: the allowance still cannot carry past (-44, 18).
    let corner = NO_ROUTE_CREDIT_CORNER;
    let units = 6;
    for (let frame = 0; frame < 40; frame += 1) {
      const step = nextRouteCredit(CG_ROUTE_COMMON, CAPTURED_CUR, units, 0.5, corner);
      units = step.units;
      corner = step.corner;
      if (units > 6) break;
    }
    expect(units).toBeLessThanOrEqual(8 + 1e-9);
    expect(units).toBeCloseTo(6.294483000367848, 9);
  });
});
